import { RendererCanvas } from './base/RendererCanvas';

import { Vector3, fieldAttractors } from './base/Vector3';

export class Solution extends RendererCanvas {

	t = 0.0;

	x0=-300.0;
	x1=300.0;
	y0=-300.0;
	y1=300.0;

	rx=50;
	ry=50;

	vs = []
	values = []

	constructor(id: string) {
		super(document.getElementById(id) as HTMLDivElement);
		this.ctx.translate(this.ctx.canvas.width * 0.5, this.ctx.canvas.height * 0.5);
		// this.clear = () => { return 0 }
		this.init();
	}
	public init() {

		this.start();
	}
	public render(ctx: CanvasRenderingContext2D): void {
		this.renderDFieldAttractors(ctx)

	}
	public renderDFieldAttractors(ctx: CanvasRenderingContext2D): void {	
		const dx =(this.x1 - this.x0)/(this.rx-1.0);
		const dy =(this.y1 - this.y0)/(this.ry-1.0);
	
		const mousep =new Vector3(this.m[0], this.m[1], 0.0);
		const p = new Vector3();
	

		for(let j=0; j<this.ry; ++j) {
			p.y=this.y0+j*dy;
			for(let i=0; i<this.rx; ++i) {
				p.x=this.x0+i*dx;
				
				const df = fieldAttractors(this.vs, this.values, p );	
				const p1=Vector3.add(p, df);

				ctx.beginPath()
				ctx.moveTo(p.x, p.y)
				ctx.lineTo(p1.x, p1.y)
				ctx.stroke();
			}
		}

		this.drawCurve(mousep, 1000, 2.0);
		this.drawCurve(mousep, 1000, -2.0);

		this.t += 0.1;
	}
	public mouseClick(x: number, y: number): void {
		// if (mouseButton==LEFT) {
			this.values.push(20.0);
		// }
		// else {
		// 	s.add(-20.0);
		// }
		const mousep = new Vector3(this.m[0], this.m[1], 0.0);
		this.vs.push(mousep);
	}
	public drawCurve = (p0: Vector3, steps: number, ds: number)  => {
		const p=new Vector3();
		p.set(p0);
	  
		this.ctx.beginPath();
		this.ctx.moveTo(p.x, p.y)

		for(let i=0; i< steps; ++i) {
			this.ctx.lineTo(p.x, p.y);

			const fv=fieldAttractors(this.vs, this.values, p);
			fv.normalize();
			fv.mult(ds);
			p.add(fv);
		}
		this.ctx.stroke();
	}
}
